/**
 * French for the whole interface without touching every page.
 *
 * The pages are written in Arabic and English (`isAr ? "…" : "…"`), so in French they render
 * their English text. This layer swaps that English for French as it appears, from one
 * dictionary (fr-ui.json, generated by scripts/i18n_extract.py and translated once):
 *  - exact sentences ("Pay from Balance" → "Payer depuis le solde"),
 *  - templates for sentences built with values ("Paid {0} of {1}" → "Payé {0} sur {1}").
 * It covers text and the placeholder / title / aria-label / alt attributes, including dialogs
 * opened later (a MutationObserver), and leaves alone anything marked translate="no",
 * user input and code. The t() keys have their own French (fr-keys.json) in LanguageContext.
 *
 * Leaving French reloads the page (LanguageContext), so nothing has to be swapped back.
 */

type Template = { re: RegExp; out: string };

const ATTRS = ["placeholder", "title", "aria-label", "alt"] as const;
const SKIP_TAGS = new Set(["SCRIPT", "STYLE", "NOSCRIPT", "CODE", "PRE", "TEXTAREA", "INPUT", "SELECT", "OPTION"]);

let exact = new Map<string, string>();
let templates: Template[] = [];
const misses = new Set<string>();
// What this layer last wrote, so its own writes (and React re-setting the same French) are not
// translated again.
const written = new WeakMap<Node, string>();
let observer: MutationObserver | null = null;
let enabled = false;

const norm = (s: string) => s.replace(/\s+/g, " ").trim();
const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

function build(dict: Record<string, string>) {
  exact = new Map();
  templates = [];
  for (const [en, fr] of Object.entries(dict)) {
    if (!fr) continue;
    if (/\{\d+\}/.test(en)) {
      // "Paid {0} of {1}" → /^Paid (.+?) of (.+?)$/ ; a template that is only placeholders is skipped.
      const literal = en.replace(/\{\d+\}/g, "").trim();
      if (!literal) continue;
      const order: number[] = [];
      const source = escapeRe(en).replace(/\\\{(\d+)\\\}/g, (_m, n) => {
        order.push(Number(n));
        return "(.+?)";
      });
      const out = fr.replace(/\{(\d+)\}/g, (_m, n) => `{${order.indexOf(Number(n))}}`);
      templates.push({ re: new RegExp(`^${source}$`), out });
    } else {
      exact.set(norm(en), fr);
    }
  }
  // Longer (more specific) templates first.
  templates.sort((a, b) => b.re.source.length - a.re.source.length);
}

// Dates the pages format in English ("Jun 10, 2026", "October 28, 2026 at 17:25", "Oct 2026").
const MONTHS = ([
  ["Jan(?:uary)?", "janv."], ["Feb(?:ruary)?", "févr."], ["Mar(?:ch)?", "mars"], ["Apr(?:il)?", "avr."],
  ["May", "mai"], ["June?", "juin"], ["July?", "juil."], ["Aug(?:ust)?", "août"],
  ["Sep(?:t(?:ember)?)?", "sept."], ["Oct(?:ober)?", "oct."], ["Nov(?:ember)?", "nov."], ["Dec(?:ember)?", "déc."],
] as [string, string][]).map(([en, fr]): [RegExp, string] => [new RegExp(`^(?:${en})\\.?$`), fr]);
const MONTH = "(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|June?|July?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\\.?";
const frMonth = (m: string) => MONTHS.find(([re]) => re.test(m))?.[1] ?? m;

/** The text with its English dates in French; the same text if it has none. */
function frenchDates(text: string): string {
  if (MONTHS.some(([re]) => re.test(text))) return frMonth(text); // a lone month ("Jan" on a chart)
  return text
    .replace(new RegExp(`\\b${MONTH} (\\d{1,2}),? (\\d{4})(?: at (\\d{1,2}:\\d{2}))?`, "g"),
      (_m, mo, d, y, time) => `${d} ${frMonth(mo)} ${y}${time ? ` à ${time}` : ""}`)
    .replace(new RegExp(`\\b${MONTH} (\\d{1,2}),? (\\d{1,2}:\\d{2})`, "g"), (_m, mo, d, time) => `${d} ${frMonth(mo)}, ${time}`)
    .replace(new RegExp(`\\b${MONTH} (\\d{1,2})\\b(?![,:\\d])`, "g"), (_m, mo, d) => `${d} ${frMonth(mo)}`)
    .replace(new RegExp(`\\b${MONTH} '?(\\d{2}|\\d{4})\\b`, "g"), (_m, mo, y) => `${frMonth(mo)} ${y}`);
}

/** French for one piece of English text, keeping its surrounding spaces; null if unknown. */
export function translate(text: string): string | null {
  const key = norm(text);
  if (!key || !/[A-Za-z]/.test(key) || misses.has(key)) return null;
  let fr = exact.get(key);
  if (fr === undefined) {
    for (const t of templates) {
      const m = key.match(t.re);
      if (m) {
        // A filled-in value that is itself known text is translated too
        // ("Receipt — Purchase paid from the wallet" → "Reçu — Achat payé depuis le portefeuille").
        fr = t.out.replace(/\{(\d+)\}/g, (_x, i) => {
          const value = m[Number(i) + 1] ?? "";
          return (value !== key && translate(value)) || value;
        });
        break;
      }
    }
  }
  if (fr === undefined) {
    const dated = frenchDates(key);
    if (dated !== key) fr = dated;
  }
  if (fr === undefined) {
    misses.add(key);
    return null;
  }
  const lead = text.match(/^\s*/)?.[0] ?? "";
  const trail = text.match(/\s*$/)?.[0] ?? "";
  return lead + fr + trail;
}

/**
 * A value the server sends in English and a French sentence takes in (a notification's
 * "{kind}", "{role}", "{what}"): its French while French is on, otherwise the value as is.
 * A lower-case word is looked up capitalised too ("developer" → "promoteur").
 */
export function translateValue(value: string): string {
  if (!enabled || !value) return value;
  const fr = translate(value);
  if (fr !== null) return fr;
  if (/^[a-z][a-z ]*$/.test(value)) {
    const cap = translate(value[0].toUpperCase() + value.slice(1));
    if (cap !== null) return cap.toLowerCase();
  }
  return value;
}

function skipped(el: Element | null): boolean {
  for (let e = el; e; e = e.parentElement) {
    if (SKIP_TAGS.has(e.tagName)) return true;
    if (e.getAttribute("translate") === "no" || e.classList.contains("notranslate")) return true;
    if ((e as HTMLElement).isContentEditable) return true;
  }
  return false;
}

function textNode(node: Text) {
  const value = node.nodeValue ?? "";
  if (written.get(node) === value || skipped(node.parentElement)) return;
  const fr = translate(value);
  if (fr !== null && fr !== value) {
    written.set(node, fr);
    node.nodeValue = fr;
  }
}

function attributes(el: Element) {
  if (skipped(el)) return;
  for (const name of ATTRS) {
    const value = el.getAttribute(name);
    if (!value) continue;
    const fr = translate(value);
    if (fr !== null && fr !== value) el.setAttribute(name, fr);
  }
}

function walk(root: Node) {
  if (root.nodeType === Node.TEXT_NODE) {
    textNode(root as Text);
    return;
  }
  if (root.nodeType !== Node.ELEMENT_NODE) return;
  const el = root as Element;
  attributes(el);
  const it = document.createTreeWalker(el, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  for (let n = it.nextNode(); n; n = it.nextNode()) {
    if (n.nodeType === Node.TEXT_NODE) textNode(n as Text);
    else attributes(n as Element);
  }
}

/** Turn French on for the whole document (idempotent). */
export function enableFrench(dict: Record<string, string>) {
  build(dict);
  misses.clear();
  enabled = true;
  walk(document.body);
  if (document.title) {
    const t = translate(document.title);
    if (t) document.title = t;
  }
  observer?.disconnect();
  observer = new MutationObserver((mutations) => {
    for (const m of mutations) {
      if (m.type === "characterData") textNode(m.target as Text);
      else if (m.type === "attributes") attributes(m.target as Element);
      else m.addedNodes.forEach(walk);
    }
  });
  observer.observe(document.body, {
    subtree: true,
    childList: true,
    characterData: true,
    attributes: true,
    attributeFilter: [...ATTRS],
  });
}
